export default function prepareSpeechInput({french_text,voice_id}) {
  if(typeof french_text!=='string'||!french_text.trim()||Array.from(french_text).length>10000) throw new Error('Supply French text with 1–10000 characters.');
  if(typeof voice_id!=='string'||!voice_id.trim()) throw new Error('Supply an ElevenLabs voice ID.');
  return {frenchText:french_text,voiceId:voice_id.trim()};
}

